from __future__ import annotations

"""Drive one tool-calling round end to end and keep the message history.

This is what the agent loop calls: hand it the assistant message the model
returned, and it runs the tools, validates the pairing, appends everything to
the running transcript, and returns the tool messages it produced.
"""

from agent_turn import (
    build_followup_messages,
    resolve_tool_calls,
    validate_tool_pairing,
)
from tool_call_models import AssistantTurn, ToolResultMessage
from tool_registry import ToolRegistry, build_support_tool_registry


class Conversation:
    def __init__(
        self,
        registry: ToolRegistry | None = None,
        system_prompt: str | None = None,
    ) -> None:
        self._registry = registry if registry is not None else build_support_tool_registry()
        self._messages: list[dict] = []
        if system_prompt:
            self._messages.append({"role": "system", "content": system_prompt})

    @property
    def messages(self) -> list[dict]:
        return list(self._messages)

    def add_user(self, content: str) -> None:
        self._messages.append({"role": "user", "content": content})

    def run_tool_round(self, assistant_message: dict) -> list[ToolResultMessage]:
        """Resolve the tool calls in an assistant message and record the round."""

        turn = AssistantTurn.from_message(assistant_message)
        tool_messages = resolve_tool_calls(turn, self._registry)
        validate_tool_pairing(turn, tool_messages)

        followup = build_followup_messages(assistant_message, tool_messages)
        self._messages.extend(followup)
        return tool_messages

    def result_for(self, tool_call_id: str) -> str | None:
        """Return the recorded content paired to a given tool_call_id."""

        for message in self._messages:
            if message.get("role") == "tool" and message.get("tool_call_id") == tool_call_id:
                return message.get("content")
        return None

    def tool_message_count(self) -> int:
        return sum(1 for m in self._messages if m.get("role") == "tool")

    def answered_tool_call_ids(self) -> list[str]:
        return [
            m["tool_call_id"]
            for m in self._messages
            if m.get("role") == "tool" and "tool_call_id" in m
        ]

    def transcript_roles(self) -> list[str]:
        return [m.get("role", "") for m in self._messages]

    def reset(self, keep_system: bool = True) -> None:
        """Clear history, optionally preserving a leading system message."""

        if keep_system and self._messages and self._messages[0].get("role") == "system":
            self._messages = [self._messages[0]]
        else:
            self._messages = []


def run_single_round(
    assistant_message: dict,
    registry: ToolRegistry | None = None,
) -> dict[str, str]:
    """Convenience: run one round and return a tool_call_id -> content map."""

    conversation = Conversation(registry=registry)
    tool_messages = conversation.run_tool_round(assistant_message)
    return {m.tool_call_id: m.content for m in tool_messages}

