from __future__ import annotations

"""Typed view of an assistant turn that asks for one or more tool calls.

A Chat Completions assistant message that wants tools looks like::

    {
        "role": "assistant",
        "content": null,
        "tool_calls": [
            {"id": "call_a", "type": "function",
             "function": {"name": "check_inventory",
                          "arguments": "{\\"sku\\": \\"SKU-A\\"}"}},
            {"id": "call_b", "type": "function",
             "function": {"name": "check_inventory",
                          "arguments": "{\\"sku\\": \\"SKU-B\\"}"}}
        ]
    }

The model can emit several calls in one turn (parallel tool calls), including
two calls to the *same* tool with different arguments. Each call carries its
own ``id``; the follow-up request must answer every ``id`` exactly once.
"""

import json
from dataclasses import dataclass


class ToolArgumentError(ValueError):
    """Raised when a tool call carries arguments that are not valid JSON."""


@dataclass(frozen=True)
class ToolCall:
    id: str
    name: str
    arguments_json: str

    def __post_init__(self) -> None:
        if not self.id or not str(self.id).strip():
            raise ValueError("tool call id is required")
        if not self.name or not str(self.name).strip():
            raise ValueError("tool call name is required")

    @classmethod
    def from_raw(cls, raw: dict) -> "ToolCall":
        function = raw.get("function") or {}
        return cls(
            id=str(raw.get("id", "")).strip(),
            name=str(function.get("name", "")).strip(),
            arguments_json=function.get("arguments") or "{}",
        )

    def parsed_arguments(self) -> dict:
        try:
            parsed = json.loads(self.arguments_json)
        except json.JSONDecodeError as exc:
            raise ToolArgumentError(f"call {self.id} has invalid JSON arguments") from exc
        if not isinstance(parsed, dict):
            raise ToolArgumentError(f"call {self.id} arguments must be a JSON object")
        return parsed


@dataclass(frozen=True)
class AssistantTurn:
    content: str | None
    tool_calls: tuple[ToolCall, ...]

    @classmethod
    def from_message(cls, message: dict) -> "AssistantTurn":
        raw_calls = message.get("tool_calls") or []
        calls = tuple(ToolCall.from_raw(rc) for rc in raw_calls)
        return cls(content=message.get("content"), tool_calls=calls)

    def wants_tools(self) -> bool:
        return len(self.tool_calls) > 0

    def call_ids(self) -> list[str]:
        return [call.id for call in self.tool_calls]


@dataclass(frozen=True)
class ToolResultMessage:
    """A ``role: tool`` reply the API pairs back to one assistant tool call."""

    tool_call_id: str
    name: str
    content: str

    def to_message(self) -> dict[str, str]:
        return {
            "role": "tool",
            "tool_call_id": self.tool_call_id,
            "name": self.name,
            "content": self.content,
        }

