from __future__ import annotations

"""Execute the tool calls in an assistant turn.

The dispatcher walks every call the model emitted, runs the matching handler in
the registry, and collects the raw result strings for the turn resolver to wrap
into ``tool`` messages. Tool-side failures are captured as error payloads so the
model can recover instead of the whole round crashing.
"""

import json

from tool_call_models import AssistantTurn, ToolArgumentError, ToolCall
from tool_registry import ToolRegistry, UnknownToolError


def _error_payload(message: str) -> str:
    return json.dumps({"error": message})


def run_call(call: ToolCall, registry: ToolRegistry) -> str:
    """Run one tool call and return its result content as a string."""

    try:
        arguments = call.parsed_arguments()
    except ToolArgumentError as exc:
        return _error_payload(str(exc))

    try:
        return registry.invoke(call.name, arguments)
    except UnknownToolError:
        return _error_payload(f"unknown tool: {call.name}")


def dispatch_all(turn: AssistantTurn, registry: ToolRegistry) -> dict[str, str]:
    """Run all calls in the turn and collect their results.

    Returns a mapping the turn resolver reads when it builds the tool messages
    that answer this turn.
    """

    results: dict[str, str] = {}
    for call in turn.tool_calls:
        results[call.name] = run_call(call, registry)
    return results


def result_is_error(result: str) -> bool:
    """True when a result string is one of the captured error payloads."""

    try:
        parsed = json.loads(result)
    except json.JSONDecodeError:
        return False
    return isinstance(parsed, dict) and "error" in parsed


def count_errors(results: dict[str, str]) -> int:
    return sum(1 for content in results.values() if result_is_error(content))


class ToolDispatcher:
    """Stateful wrapper that also tracks how many calls it has run."""

    def __init__(self, registry: ToolRegistry) -> None:
        self._registry = registry
        self._calls_run = 0

    @property
    def calls_run(self) -> int:
        return self._calls_run

    def dispatch(self, turn: AssistantTurn) -> dict[str, str]:
        results: dict[str, str] = {}
        for call in turn.tool_calls:
            results[call.name] = run_call(call, self._registry)
            self._calls_run += 1
        return results

    def dispatch_with_report(self, turn: AssistantTurn) -> dict[str, object]:
        """Run the turn and return results plus a small health summary."""

        results = self.dispatch(turn)
        return {
            "results": results,
            "calls_in_turn": len(turn.tool_calls),
            "error_count": count_errors(results),
        }

    def registry(self) -> ToolRegistry:
        return self._registry

