from __future__ import annotations

"""The functions the support agent is allowed to call.

Each handler takes the parsed argument dict and returns a JSON string, which is
exactly what gets handed back to the model as the ``tool`` message content.
Handlers are deterministic so a given argument always maps to the same answer.
"""

import json
from typing import Callable


class UnknownToolError(KeyError):
    """Raised when the model asks for a tool that is not registered."""


# Tiny fixed datasets so results vary by argument, not by call order.
_INVENTORY = {
    "SKU-A": 5,
    "SKU-B": 0,
    "SKU-C": 42,
}

_ORDERS = {
    "ORD-100": {"status": "shipped", "carrier": "ups"},
    "ORD-200": {"status": "processing", "carrier": None},
    "ORD-300": {"status": "delivered", "carrier": "fedex"},
}

_ETA_DAYS_BY_REGION = {
    "west": 2,
    "central": 3,
    "east": 4,
}


def _check_inventory(args: dict) -> str:
    sku = str(args.get("sku", "")).strip()
    available = _INVENTORY.get(sku)
    return json.dumps(
        {
            "sku": sku,
            "in_stock": available is not None and available > 0,
            "quantity": available if available is not None else 0,
        }
    )


def _get_order_status(args: dict) -> str:
    order_id = str(args.get("order_id", "")).strip()
    record = _ORDERS.get(order_id)
    if record is None:
        return json.dumps({"order_id": order_id, "found": False})
    return json.dumps({"order_id": order_id, "found": True, **record})


def _get_shipping_eta(args: dict) -> str:
    region = str(args.get("region", "")).strip().lower()
    days = _ETA_DAYS_BY_REGION.get(region)
    return json.dumps(
        {
            "region": region,
            "eta_days": days if days is not None else 7,
            "expedited": bool(args.get("expedited", False)),
        }
    )


class ToolRegistry:
    def __init__(self) -> None:
        self._handlers: dict[str, Callable[[dict], str]] = {}

    def register(self, name: str, handler: Callable[[dict], str]) -> None:
        self._handlers[name] = handler

    def is_registered(self, name: str) -> bool:
        return name in self._handlers

    def invoke(self, name: str, arguments: dict) -> str:
        handler = self._handlers.get(name)
        if handler is None:
            raise UnknownToolError(name)
        return handler(arguments)

    def tool_names(self) -> list[str]:
        return sorted(self._handlers)


def build_support_tool_registry() -> ToolRegistry:
    registry = ToolRegistry()
    registry.register("check_inventory", _check_inventory)
    registry.register("get_order_status", _get_order_status)
    registry.register("get_shipping_eta", _get_shipping_eta)
    return registry

