import json

import pytest

from tool_call_models import AssistantTurn, ToolArgumentError
from tool_dispatcher import dispatch_all
from agent_turn import (
    ToolPairingError,
    resolve_tool_calls,
    validate_tool_pairing,
)
from conversation import Conversation, run_single_round
from tool_registry import build_support_tool_registry


def call(call_id, name, **arguments):
    return {
        "id": call_id,
        "type": "function",
        "function": {"name": name, "arguments": json.dumps(arguments)},
    }


def assistant_message(*calls, content=None):
    return {"role": "assistant", "content": content, "tool_calls": list(calls)}


def registry():
    return build_support_tool_registry()


def test_single_tool_call_resolves_happy_path():
    msg = assistant_message(call("call_1", "get_order_status", order_id="ORD-100"))
    results = run_single_round(msg, registry())

    assert set(results) == {"call_1"}
    assert json.loads(results["call_1"])["status"] == "shipped"


def test_parallel_distinct_tools_each_get_their_result():
    msg = assistant_message(
        call("call_inv", "check_inventory", sku="SKU-C"),
        call("call_ord", "get_order_status", order_id="ORD-300"),
    )
    results = run_single_round(msg, registry())

    assert json.loads(results["call_inv"])["quantity"] == 42
    assert json.loads(results["call_ord"])["status"] == "delivered"


def test_same_tool_called_twice_keeps_results_per_call_id():
    # The model checks two SKUs in one turn. Each call id must receive its own
    # answer, not a single collapsed result.
    msg = assistant_message(
        call("call_a", "check_inventory", sku="SKU-A"),
        call("call_b", "check_inventory", sku="SKU-B"),
    )
    results = run_single_round(msg, registry())

    assert json.loads(results["call_a"])["sku"] == "SKU-A"
    assert json.loads(results["call_a"])["quantity"] == 5
    assert json.loads(results["call_b"])["sku"] == "SKU-B"
    assert json.loads(results["call_b"])["quantity"] == 0


def test_same_tool_three_times_does_not_drop_any_call():
    msg = assistant_message(
        call("c1", "check_inventory", sku="SKU-A"),
        call("c2", "check_inventory", sku="SKU-B"),
        call("c3", "check_inventory", sku="SKU-C"),
    )
    results = run_single_round(msg, registry())

    assert set(results) == {"c1", "c2", "c3"}
    assert json.loads(results["c1"])["quantity"] == 5
    assert json.loads(results["c2"])["quantity"] == 0
